import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class TypeInferenceDemo {
    public static void main(String[] args) {
        // Leveraging the diamond operator for complex nested generics
        Map<String, List<String>> departmentDirectory = new HashMap<>();

        departmentDirectory.put("Engineering", new ArrayList<>());
        departmentDirectory.get("Engineering").add("Backend Team");

        // Combining local variable type inference (var) with the diamond operator
        var activeSessions = new HashMap<Long, String>();
        activeSessions.put(1001L, "Active");

        System.out.println("Directory initialized successfully: " + departmentDirectory);
    }
}
